with
  batch := to_json('[{\"sku\":\"A\",\"name\":\"Test\",\"price_cents\":100,\"stock\":5,\"category\":\"tools\"}]'),
  records := json_array_unpack(batch),
  for r in records union (
    select {
      sku := <str>r['sku'],
      tags := <str>json_array_unpack(json_get(r, 'tags') ?? to_json('[]'))
    }
  )
" 2>&1

cd /home/user/catalog-sync && /home/user/catalog-sync/node_modules/.bin/gel query "
with
  batch := to_json('[{\"sku\":\"A\",\"name\":\"Test\",\"price_cents\":100,\"stock\":5,\"category\":\"tools\",\"tags\":[\"metal\"]}]'),
  records := json_array_unpack(batch),
  -- categories
  _cat := (
    for r in records union (
      insert Category { name := <str>r['category'] }
      unless conflict on .name
      else (select Category filter .name = <str>r['category'])
    )
  ),
  -- tags
  _tag := (
    for r in records union (
      for tag_label in json_array_unpack(json_get(r, 'tags') ?? to_json('[]')) union (
        insert Tag { label := <str>tag_label }
        unless conflict on .label
        else (select Tag filter .label = <str>tag_label)
      )
    )
  ),
  results := (
    for r in records union (
      with
        sku := <str>r['sku'],
        existing := (select Product filter .sku = sku),
        cat := assert_single((select Category filter .name = <str>r['category'])),
        tag_labels := json_array_unpack(json_get(r, 'tags') ?? to_json('[]')),
        desired_tags := (select Tag filter .label in array_agg(<str>tag_labels)),
        outcome := (
          if not exists existing then 'inserted'
          else if (
            existing.name != <str>r['name']
            or existing.price_cents != <int64>r['price_cents']
            or existing.stock != <int64>r['stock']
            or existing.category != cat
            or count(existing.tags) != count(desired_tags)
            or exists (existing.tags except desired_tags)
          ) then 'updated'
          else 'unchanged'
        ),
        _product := (
          insert Product {
            sku := sku,
            name := <str>r['name'],
            price_cents := <int64>r['price_cents'],
            stock := <int64>r['stock'],
            category := cat,
            tags := desired_tags
          }
          unless conflict on .sku
          else (
            update Product set {
              name := <str>r['name'],
              price_cents := <int64>r['price_cents'],
              stock := <int64>r['stock'],
              category := cat,
              tags := desired_tags
            }
          )
        )
      select {
        sku := sku,
        outcome := outcome,
        category := <str>r['category'],
        tags := array_agg((select <str>tag_labels order by @value))
      }
    )
  )
select results
" 2>&1

